import {Globe} from './globe.js';
import {MIN_YEAR,MAX_YEAR,epochs,formatYear,activeAt,yearToPosition,positionToYear,parseYear,matches,activeRelations} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const regionColors={Африка:'#d8bd7c',Европа:'#a4c5b5',Азия:'#c7db9b',Америка:'#dca991',Океания:'#a8c4cf'};
let data,globe,timer=null,year=-2560,mode='cultures',selected='egypt-old',q='',region='all',relationType='all';
const period=c=>`${c.approximate?'ок. ':''}${formatYear(c.start)} — ${formatYear(c.end)}`;
const sourceLinks=ids=>[...new Set(ids)].map(id=>{const s=data.sources[id];return s?`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`:'';}).join('');
const color=c=>mode==='religions'?(data.religions[c.religions[0]]?.color||'#c0b68e'):regionColors[c.region]||'#c4d28a';
const current=()=>activeAt(data.cultures,year);
const visible=()=>current().filter(c=>(region==='all'||c.region===region)&&(!q||matches(c,q)));
const links=()=>activeRelations(data,year,relationType);
function persist(){const p=new URLSearchParams({year:String(year),mode,culture:selected||''});history.replaceState(null,'','#'+p);try{localStorage.setItem('chronos-state-v1',JSON.stringify({year,mode,selected}));}catch{}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function selectCulture(id,focus=true){const c=data.cultures.find(c=>c.id===id);if(!c)return;selected=id;if(year<c.start||year>c.end){stop();year=Math.max(c.start,Math.min(c.end,year));toast(`Переход: ${formatYear(year)}`);}render();if(focus)globe.focus(c.coordinates);}
function setYear(y){year=y;const cs=current();if(!cs.some(c=>c.id===selected))selected=cs[0]?.id||null;render();}
function setMode(m){mode=m;render();}
function render(){const list=visible(),allCurrent=current();if(selected&&!allCurrent.some(c=>c.id===selected))selected=null;
 $('#worldDate').innerHTML=`${Math.abs(year).toLocaleString('ru-RU')} <small>${year<0?'до н. э.':'н. э.'}</small>`;
 let epoch=epochs[0];for(const e of epochs)if(year>=e.start)epoch=e;$('#epochLabel').textContent=epoch.name.toUpperCase();
 $('#timeRange').value=yearToPosition(year);$('#timeRange').setAttribute('aria-valuetext',formatYear(year));$('#yearInput').value=Math.abs(year);$('#era').value=year<0?'bce':'ce';$('#count').textContent=allCurrent.length;$('#relationType').hidden=mode!=='relations';
 $$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode);});
 $$('[data-epoch]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.epoch)===epoch.year);});
 const rows=(q?data.cultures.filter(c=>matches(c,q)&&(region==='all'||c.region===region)):list);
 $('#cultureList').innerHTML=rows.length?rows.map(c=>`<button class="culture-row ${c.id===selected?'selected':''}" data-culture="${c.id}" aria-pressed="${c.id===selected}"><span class="swatch" style="background:${color(c)}"></span><span><strong>${esc(c.name)}</strong><small>${esc(c.region)}${c.start<=year&&year<=c.end?' · '+esc(c.kind):' · перейти к периоду'}</small></span><span class="row-arrow">↗</span></button>`).join(''):`<div class="empty">${q?'По вашему запросу нет записей. Попробуйте другое название.':'Для этого времени и региона пока нет записей.'}<button id="clearFilters">Сбросить фильтры</button></div>`;
 const displayed=mode==='relations'?list.filter(c=>links().some(r=>r.from===c.id||r.to===c.id)):list;
 globe.setData(displayed,links(),mode,selected,color);
 if(mode==='religions'){const rels=[...new Set(list.flatMap(c=>c.religions))];$('#legend').innerHTML=rels.map(id=>`<span><i style="background:${data.religions[id].color}"></i>${esc(data.religions[id].name)}</span>`).join('');}else if(mode==='relations')$('#legend').innerHTML='<span><i style="background:#c7cc8f"></i>Торговля и обмен →</span><span><i style="background:#c68e72"></i>Колониальная зависимость ⇢</span>';else $('#legend').innerHTML=Object.entries(regionColors).filter(([r])=>list.some(c=>c.region===r)).map(([r,col])=>`<span><i style="background:${col}"></i>${r}</span>`).join('');
 renderDetail();persist();
}
function renderDetail(){const c=data.cultures.find(c=>c.id===selected);if(!c){$('#detail').innerHTML=`<div class="detail-top">ПРОБЕЛ В ПОКРЫТИИ</div><h2>История ещё не добавлена</h2><p class="summary">Для выбранного года в базе пока нет записей. Это не означает, что здесь не было людей и обществ.</p><button class="primary" data-story="pyramids">Исследовать эпоху пирамид ↗</button><button class="secondary" data-about>О покрытии базы</button>`;return;}
 let content='';if(mode==='cultures'){const rulers=c.rulers.filter(r=>r.start<=year&&year<=r.end);content=`<p class="summary">${esc(c.summary)}</p><dl><div><dt>Устройство власти</dt><dd>${esc(c.government)}</dd></div><div><dt>Общество</dt><dd>${esc(c.society)}</dd></div><div><dt>Хозяйство</dt><dd>${esc(c.economy)}</dd></div><div><dt>Правитель в выбранном году</dt><dd>${rulers.length?rulers.map(r=>esc(r.name)).join(', '):'В проверенной базе пока не указан'}</dd></div></dl>`;
 const relevant=c.events.filter(e=>e.year<=year).sort((a,b)=>b.year-a.year)[0];if(relevant)content+=`<div class="event"><strong>${formatYear(relevant.year)}</strong><p>${esc(relevant.text)}</p></div>`;
 }else if(mode==='religions'){content=`<p class="summary">Традиции, зафиксированные для периода. Преобладание и доли последователей без надёжных количественных данных не оцениваются.</p>`+c.religions.map(id=>{const r=data.religions[id];return `<div class="event"><strong style="color:${r.color}">${esc(r.name)}</strong><p>${esc(r.summary)}</p><p><span class="section-label">ВОЗНИКНОВЕНИЕ</span><br>${esc(r.origin)}</p>${sourceLinks(r.sources)}</div>`;}).join('');
 }else{const rels=links().filter(r=>r.from===c.id||r.to===c.id);content=`<p class="summary">Связи в выбранном году. Линии — схема взаимодействий, без реконструкции точных путей.</p>`+(rels.length?rels.map(r=>`<div class="relation-card"><span class="relation-tag">${r.type==='colonial'?'Колониальная зависимость':'Торговля и обмен'}</span><strong>${esc(r.title)}</strong><p>${esc(r.goods)}.</p><p>${esc(r.returns)}.</p><p>${esc(r.impact)}</p>${sourceLinks(r.sources)}<button data-culture="${r.from===c.id?r.to:r.from}">Открыть другую сторону ↗</button></div>`).join(''):'<p class="summary">Для этой культуры в выбранном году и фильтре проверенные связи пока не добавлены.</p>');}
 $('#detail').innerHTML=`<div class="detail-top"><span>${esc(c.region.toUpperCase())}</span><span class="type-label">${esc(c.kind)}</span></div><h2>${esc(c.name)}</h2><div class="period">${period(c)}</div>${content}<button class="primary" id="compare">Сравнить с современниками ↗</button><button class="secondary" id="selectedSources">Источники и примечания</button><p class="uncertainty">${esc(c.note)}</p>`;
}
function modal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function about(){modal(`<h2>История без иллюзии полноты.</h2><p>Хронос позволяет посмотреть на разные общества в один момент времени. Это первая исследовательская версия: база выборочная и не претендует на охват всех эпох, наций, правителей и религий.</p><div class="stat-grid"><span><strong>${data.cultures.length}</strong><small>исторических обзора</small></span><span><strong>${data.relations.length}</strong><small>связей</small></span><span><strong>${Object.keys(data.sources).length}</strong><small>источника</small></span></div><h3>Что именно показывает глобус</h3><p>Точки обозначают ориентировочные центры присутствия или места памятников. Это не исторические границы. Современная береговая линия взята из Natural Earth (общественное достояние). Ранние общества не отождествляются с современными нациями. Линии связей схематичны; некоторые обмены происходили через цепочки посредников.</p><h3>Как читать датировки</h3><p>Доисторические интервалы округлены. Диапазон карточки — рамки обзора, а не гарантия неизменности общества. Названия эпох — условная навигация: периодизация отличается по регионам. Шкала нелинейная: древним эпохам и недавним столетиям отведено сопоставимое место. Года 0 нет. Точный ввод поддерживается от 100 000 до н. э. до 2025 н. э.; точность выбора года не означает такую же точность реконструкции.</p><h3>Верования и власть</h3><p>Цвет означает выбранную в обзоре традицию, а не религиозную однородность или долю верующих. В карточках перечислены также сосуществующие традиции. «Реконструкция ограничена» означает недостаток данных для уверенного описания, а не отсутствие верований. Правители показаны только там, где есть датированные записи.</p><h3>Источники и развитие базы</h3><p>Краткие тексты — авторские обзоры по музейным, научным и институциональным материалам; они ещё не прошли независимое научное рецензирование. Африка, Америка и особенно Океания пока представлены неравномерно. Каждая запись хранит источники и примечания отдельно; дополнения и исправления можно предлагать в репозитории. Обновление базы: ${data.updated}.</p><div class="source-index">${sourceLinks(Object.keys(data.sources))}</div><p>География: Natural Earth, public domain. Визуализация: D3, ISC © Mike Bostock. Приложение не использует платные API. Шрифты Google Fonts загружаются при наличии сети; предусмотрены системные замены.</p>`);}
function showSources(){const c=data.cultures.find(c=>c.id===selected);if(!c)return;modal(`<h2>${esc(c.name)}<br>Источники и оговорки</h2><p>${esc(c.note)}</p><p>${period(c)}. Для точных событий и спорных интерпретаций сверяйтесь с первоисточниками. Карточка — краткий обзор, а не полная библиография.</p><div class="source-index">${sourceLinks(c.sources)}</div>`);}
function compare(aId=selected,bId){const cs=current(),a=cs.find(c=>c.id===aId)||cs[0],b=cs.find(c=>c.id===bId)||cs.find(c=>c.id!==a?.id);if(!a||!b){toast('Для сравнения нужны как минимум две записи в одном году.');return;}const opts=id=>cs.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('');modal(`<span class="eyebrow">ОДНОВРЕМЕННО НА ЗЕМЛЕ / ${formatYear(year)}</span><h2>Разные миры. Один год.</h2><div class="compare-chooser"><select id="compareA" aria-label="Первая культура">${opts(a.id)}</select><select id="compareB" aria-label="Вторая культура">${opts(b.id)}</select></div><div class="comparison">${[a,b].map(c=>`<article><h3>${esc(c.name)}</h3><span class="eyebrow">${esc(c.region)}</span><p>${esc(c.summary)}</p><span class="compare-label">УСТРОЙСТВО ОБЩЕСТВА</span><p>${esc(c.government)}. ${esc(c.society)}</p><span class="compare-label">ХОЗЯЙСТВО</span><p>${esc(c.economy)}</p><span class="compare-label">ВЕРОВАНИЯ</span><p>${c.religions.map(id=>esc(data.religions[id].name)).join(', ')}</p>${sourceLinks(c.sources)}<p>${esc(c.note)}</p></article>`).join('')}</div><p>Сосуществование во времени само по себе не доказывает контактов между обществами.</p>`);$('#compareA').onchange=()=>compare($('#compareA').value,$('#compareB').value);$('#compareB').onchange=()=>compare($('#compareA').value,$('#compareB').value);}
function story(name){stop();q='';region='all';relationType='all';$('#search').value='';$('#region').value='all';$('#relationType').value='all';if(name==='pyramids'){year=-2560;mode='cultures';selected='egypt-old';render();globe.focus([31,20]);compare('egypt-old','caral');}else if(name==='novgorod'){year=1250;mode='relations';selected='novgorod';render();globe.focus([24,52]);toast('1250 год: выбраны связи Новгорода.');}else{year=1600;mode='relations';selected='potosi';render();globe.focus([-40,-3]);toast('1600 год: выбрана связь Потоси и Испании.');}$('#atlasNav').focus({preventScroll:true});if(name!=='pyramids')$('.workspace').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
function stop(){clearInterval(timer);timer=null;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Запустить путешествие по временной шкале');}
function bind(){document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.culture)selectCulture(b.dataset.culture);if(b.dataset.mode)setMode(b.dataset.mode);if(b.dataset.epoch){stop();setYear(Number(b.dataset.epoch));}if(b.dataset.story)story(b.dataset.story);if(b.hasAttribute('data-about'))about();if(b.id==='clearFilters'){q='';region='all';$('#search').value='';$('#region').value='all';render();}if(b.id==='compare')compare();if(b.id==='selectedSources')showSources();});
 $('#yearForm').addEventListener('submit',e=>{e.preventDefault();const y=parseYear($('#yearInput').value,$('#era').value);if(y===null){$('#yearError').textContent=`Введите целый год без нуля: от 100 000 до н. э. до ${MAX_YEAR} н. э.`;return;}$('#yearError').textContent='';stop();setYear(y);});
 $('#timeRange').addEventListener('input',e=>{stop();$('#yearError').textContent='';setYear(positionToYear(Number(e.target.value)));});
 $('#search').oninput=e=>{q=e.target.value;render();};$('#region').onchange=e=>{region=e.target.value;render();};$('#relationType').onchange=e=>{relationType=e.target.value;render();};
 $('#resetView').onclick=()=>globe.reset();$('#zoomIn').onclick=()=>globe.setZoom(globe.zoom*1.15);$('#zoomOut').onclick=()=>globe.setZoom(globe.zoom/1.15);
 $('#play').onclick=()=>{if(timer){stop();return;}if(year>=MAX_YEAR)setYear(MIN_YEAR);$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Остановить путешествие');timer=setInterval(()=>{const p=Math.min(1000,yearToPosition(year)+4);setYear(positionToYear(p));if(p>=1000)stop();},400);};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
 ['aboutNav','coverageBtn','methodNav'].forEach(id=>$('#'+id).onclick=about);$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});$('#storiesNav').onclick=()=>$('#journeys').scrollIntoView({behavior:'smooth'});$('#atlasNav').onclick=()=>$('.workspace').scrollIntoView({behavior:'smooth'});
 $('#share').onclick=async()=>{persist();try{await navigator.clipboard.writeText(location.href);toast('Ссылка на этот год и режим скопирована.');}catch{modal(`<h2>Ссылка на выбранный момент</h2><p>Скопируйте адрес:</p><input aria-label="Ссылка" style="width:100%;padding:12px" readonly value="${esc(location.href)}">`);}};
}
async function init(){try{const [d,l]=await Promise.all([fetch('data/history.json').then(r=>{if(!r.ok)throw Error('Историческая база недоступна');return r.json();}),fetch('data/land.geojson').then(r=>{if(!r.ok)throw Error('География недоступна');return r.json();})]);if(!window.d3)throw Error('Не удалось загрузить библиотеку глобуса');data=d;const params=new URLSearchParams(location.hash.slice(1));let saved=null;try{saved=JSON.parse(localStorage.getItem('chronos-state-v1'));}catch{}const raw=params.has('year')?Number(params.get('year')):saved?.year;if(Number.isInteger(raw)&&raw!==0&&raw>=MIN_YEAR&&raw<=MAX_YEAR)year=raw;const m=params.get('mode')||saved?.mode;if(['cultures','religions','relations'].includes(m))mode=m;const s=params.get('culture')||saved?.selected;if(data.cultures.some(c=>c.id===s))selected=s;if(!current().some(c=>c.id===selected))selected=current()[0]?.id||null;
 globe=new Globe($('#globe'),l,id=>selectCulture(id,false));$('#loading').hidden=true;$('#epochs').innerHTML=epochs.map(e=>`<button data-epoch="${e.year}">${esc(e.name)}</button>`).join('');const ticks=[-100000,-12000,-4000,-1000,1,1000,1800,2025];$('#ticks').innerHTML=ticks.map(y=>`<span style="left:${yearToPosition(y)/10}%">${y<0?'−':''}${Math.abs(y).toLocaleString('ru-RU')}</span>`).join('');bind();render();}catch(err){$('#loading').textContent=err.message;$('#detail').innerHTML='<h2>Атлас не загрузился</h2><p class="summary">Обновите страницу. Если ошибка сохраняется, проверьте доступность файлов приложения.</p>';console.error(err);}}
init();
